ALTER TABLE public.sales_settings ADD COLUMN IF NOT EXISTS city text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS default_currency text NOT NULL DEFAULT 'INR', ADD COLUMN IF NOT EXISTS tax_percentage numeric NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS tax_preference text NOT NULL DEFAULT 'exclusive', ADD COLUMN IF NOT EXISTS invoice_prefix text NOT NULL DEFAULT 'INV', ADD COLUMN IF NOT EXISTS invoice_business_information text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS payment_instructions text NOT NULL DEFAULT '';
ALTER TABLE public.sales_settings ADD CONSTRAINT business_settings_tax_range CHECK(tax_percentage BETWEEN 0 AND 100), ADD CONSTRAINT business_settings_tax_preference CHECK(tax_preference IN ('inclusive','exclusive')), ADD CONSTRAINT business_settings_currency CHECK(default_currency ~ '^[A-Z]{3}$'), ADD CONSTRAINT business_settings_invoice_prefix CHECK(invoice_prefix ~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,19}$');
CREATE OR REPLACE FUNCTION public.save_business_settings(_payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.can_manage_sales() THEN RAISE EXCEPTION 'Active Super Admin authorization required'; END IF;
IF length(trim(coalesce(_payload->>'company_name',''))) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Business name is required'; END IF;
INSERT INTO public.sales_settings(id,company_name,address,city,gstin,state,country,email,phone,default_currency,tax_percentage,tax_preference,invoice_prefix,invoice_business_information,payment_instructions)
VALUES(true,trim(_payload->>'company_name'),coalesce(_payload->>'address',''),coalesce(_payload->>'city',''),coalesce(_payload->>'gstin',''),coalesce(_payload->>'state',''),coalesce(_payload->>'country',''),coalesce(_payload->>'email',''),coalesce(_payload->>'phone',''),coalesce(_payload->>'default_currency','INR'),coalesce((_payload->>'tax_percentage')::numeric,0),coalesce(_payload->>'tax_preference','exclusive'),coalesce(_payload->>'invoice_prefix','INV'),coalesce(_payload->>'invoice_business_information',''),coalesce(_payload->>'payment_instructions',''))
ON CONFLICT(id) DO UPDATE SET company_name=EXCLUDED.company_name,address=EXCLUDED.address,city=EXCLUDED.city,gstin=EXCLUDED.gstin,state=EXCLUDED.state,country=EXCLUDED.country,email=EXCLUDED.email,phone=EXCLUDED.phone,default_currency=EXCLUDED.default_currency,tax_percentage=EXCLUDED.tax_percentage,tax_preference=EXCLUDED.tax_preference,invoice_prefix=EXCLUDED.invoice_prefix,invoice_business_information=EXCLUDED.invoice_business_information,payment_instructions=EXCLUDED.payment_instructions;
END $$;
REVOKE ALL ON FUNCTION public.save_business_settings(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_business_settings(jsonb) TO authenticated;
COMMENT ON FUNCTION public.save_business_settings(jsonb) IS 'Save seller details and future preferences only; never update invoices or payments.';